-- Migration: 001_create_submissions
-- Purpose: establish the migration ledger and durable lead-intake submission table.
-- PostgreSQL: 13+
-- Apply once to a disposable/development database using psql with ON_ERROR_STOP.
-- Do not edit this file after it has been applied; create a new migration instead.

BEGIN;

CREATE TABLE schema_migrations (
    version       text PRIMARY KEY,
    description   text NOT NULL,
    applied_at    timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE submissions (
    id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    source              text NOT NULL,
    source_event_key    text NOT NULL,
    payload_fingerprint text NOT NULL,
    status              text NOT NULL DEFAULT 'pending',
    correlation_id      uuid NOT NULL DEFAULT gen_random_uuid(),
    received_at         timestamptz NOT NULL DEFAULT now(),
    processed_at        timestamptz,
    error_code          text,
    schema_version      integer NOT NULL,

    CONSTRAINT submissions_source_not_blank
        CHECK (length(btrim(source)) > 0),
    CONSTRAINT submissions_source_normalized
        CHECK (source = lower(btrim(source))),
    CONSTRAINT submissions_event_key_length
    CHECK (
        length(btrim(source_event_key)) BETWEEN 1 AND 128
    ),
    CONSTRAINT submissions_fingerprint_sha256_hex
        CHECK (payload_fingerprint ~ '^[0-9a-f]{64}$'),
    CONSTRAINT submissions_status_allowed
        CHECK (status IN ('pending', 'processing', 'processed', 'review_required', 'failed')),
    CONSTRAINT submissions_schema_version_positive
        CHECK (schema_version > 0),
    CONSTRAINT submissions_source_event_key_unique
        UNIQUE (source, source_event_key)
);

CREATE INDEX submissions_status_received_at_idx
    ON submissions (status, received_at);

CREATE INDEX submissions_correlation_id_idx
    ON submissions (correlation_id);

INSERT INTO schema_migrations (version, description)
VALUES ('001', 'Create migration ledger and submissions table');

COMMIT;
